// SkyShift service worker (generated by scripts/build.mjs; do not edit dist/sw.js).
// App shell: precached and versioned. Live data: network-first (handled in the app with
// IndexedDB fallbacks). HiPS sky tiles: cache-first. Navigations work offline.

const VERSION = '__VERSION__';
const SHELL = `skyshift-shell-${VERSION}`;
const RUNTIME = 'skyshift-runtime-v1';
const HIPS = 'skyshift-hips-v1';
const PRECACHE = __PRECACHE__;
const NETWORK_FIRST = /\/(version\.json|data\/idx\/.+)$/;
// served at once from the last copy and refreshed in the background (fast start; updates arrive on the next visit)
const STALE_REVALIDATE = /\/(config\.json|data\/targets\.json)$/;

// Some hosts redirect (e.g. Cloudflare Pages sends /index.html to / with 308). Browsers refuse a response marked
// "redirected" for a page load, so every stored response is first copied into a plain, unredirected one.
async function clean(res) {
  if (!res || !res.redirected) return res;
  return new Response(await res.blob(), { status: res.status, statusText: res.statusText, headers: res.headers });
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL);
    await Promise.all(PRECACHE.map(async (u) => {
      const res = await fetch(new Request(u, { cache: 'reload' }));
      if (!res.ok) throw new Error(`precache ${u}: ${res.status}`);
      await cache.put(u, await clean(res));
    }));
    // no app page open (e.g. a visitor stuck on an error page): take over at once instead of waiting for the pop-up
    if (!(await self.clients.matchAll({ type: 'window' })).length) await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('skyshift-shell-') && k !== SHELL).map((k) => caches.delete(k)));
    if (self.registration.navigationPreload) await self.registration.navigationPreload.enable().catch(() => {});
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
  if (event.data?.type === 'RESET') event.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => k.startsWith('skyshift-shell-') || k === RUNTIME).map((k) => caches.delete(k)))));
});

async function trim(cacheName, max) {
  const c = await caches.open(cacheName);
  const keys = await c.keys();
  for (let i = 0; i < keys.length - max; i++) await c.delete(keys[i]);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  // HiPS tiles for the sky atlas (CORS-enabled at IRSA): cache-first, bounded.
  if (url.hostname === 'irsa.ipac.caltech.edu' && url.pathname.startsWith('/data/hips/')) {
    // Aladin Lite opens a HiPS cube at its middle channel; in the SPHEREx DR1 cube channels 50/51
    // (0-based) are blank by design (IRSA docs), so serve the neighbouring valid channel 49 instead.
    let target = req;
    if (/spherex_allsky_cube\/.+_(50|51)\.png$/.test(url.pathname)) target = new Request(req.url.replace(/_(50|51)\.png$/, '_49.png'), { mode: 'cors' });
    event.respondWith((async () => {
      const c = await caches.open(HIPS);
      const hit = await c.match(target);
      if (hit) return hit;
      try {
        const res = await fetch(target);
        if (res.ok) { c.put(target, res.clone()); if (Math.random() < 0.05) trim(HIPS, 1500); }
        return res;
      } catch { return hit || Response.error(); }
    })());
    return;
  }
  if (url.origin !== self.location.origin) return; // S3 range reads and API calls are handled by the app
  if (url.pathname.endsWith('/api/relay')) return;
  // The presentation (slides, PDF, video) is a separate static page: always served straight from the network
  if (url.pathname.includes('/presentation/')) return;

  // only the app's own page is served from the shell; other pages on the site (e.g. test/embed) load normally
  const scopePath = new URL(self.registration.scope).pathname;
  if (req.mode === 'navigate' && (url.pathname === scopePath || url.pathname === scopePath + 'index.html')) {
    // the page HTML comes from this version's cache, so HTML, CSP, scripts and styles always match;
    // a new version arrives through the service-worker update (and its pop-up)
    event.respondWith((async () => {
      const c = await caches.open(SHELL);
      const hit = (await c.match('./')) || (await c.match('./index.html'));
      if (hit && !hit.redirected) return hit;
      // no usable stored page: the network (never an error page while the host answers)
      try { return await clean((await event.preloadResponse) || (await fetch(req))); } catch { return hit ? clean(hit) : Response.error(); }
    })());
    return;
  }

  if (STALE_REVALIDATE.test(url.pathname)) {
    event.respondWith((async () => {
      const c = await caches.open(RUNTIME);
      const hit = (await c.match(req, { ignoreSearch: true })) || (await (await caches.open(SHELL)).match(req, { ignoreSearch: true }));
      const update = fetch(req, { cache: 'no-cache' }).then((res) => { if (res.ok) c.put(req, res.clone()); return res; }).catch(() => null);
      if (hit) { event.waitUntil(update); return hit; }
      return (await update) || Response.error();
    })());
    return;
  }

  if (NETWORK_FIRST.test(url.pathname)) {
    event.respondWith((async () => {
      try {
        const res = await fetch(req, { cache: 'no-cache' });
        if (res.ok) (await caches.open(RUNTIME)).put(req, res.clone());
        return res;
      } catch {
        return (await (await caches.open(RUNTIME)).match(req)) || (await (await caches.open(SHELL)).match(req)) || Response.error();
      }
    })());
    return;
  }

  // Shell assets come only from THIS version's cache, so old and new modules are never mixed.
  // Other same-origin files (e.g. Aladin Lite, large images): stale-while-revalidate from the runtime cache.
  event.respondWith((async () => {
    const isShell = PRECACHE.some((p) => url.pathname.endsWith(p.replace(/^\.\//, '/')) && p !== './');
    const hit = isShell ? await (await caches.open(SHELL)).match(req) : await (await caches.open(RUNTIME)).match(req);
    if (hit) {
      if (!isShell) fetch(req).then(async (res) => { if (res.ok) (await caches.open(RUNTIME)).put(req, res); }).catch(() => {});
      return hit;
    }
    try {
      const res = await fetch(req);
      // a shell file missing from the cache is put back (self-healing); others go to the runtime cache
      if (res.ok) (await caches.open(isShell ? SHELL : RUNTIME)).put(req, res.clone());
      return res;
    } catch {
      return (await (await caches.open(RUNTIME)).match(req)) || Response.error();
    }
  })());
});
